{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [{
    "@type": "Question",
    "name": "Củ tam thất khô và bột tam thất có giống nhau không?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "Về bản chất, bột tam thất thường được nghiền từ củ tam thất khô đã sơ chế. Tuy nhiên, dạng bột khó kiểm soát chất lượng nguyên liệu đầu vào hơn và dễ bị oxy hóa nếu bảo quản không tốt so với củ nguyên."
    }
  }, {
    "@type": "Question",
    "name": "Có nên dùng tam thất hằng ngày không?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "Không nên tự ý dùng tam thất hằng ngày trong thời gian dài mà không có sự giám sát. Việc sử dụng cần có liệu trình cụ thể phù hợp với thể trạng của từng người và nên tham khảo ý kiến chuyên gia y tế."
    }
  }, {
    "@type": "Question",
    "name": "Uống trà hoa tam thất có chữa mất ngủ không?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "Trà hoa tam thất có thể hỗ trợ thư giãn nhẹ nhàng, nhưng chưa có đủ bằng chứng y khoa để khẳng định nó có thể chữa trị chứng mất ngủ mãn tính. Hãy xem đây là thức uống hỗ trợ, không phải thuốc điều trị."
    }
  }, {
    "@type": "Question",
    "name": "Những ai không nên dùng tam thất?",
    "acceptedAnswer": {
      "@type": "Answer",
      "text": "Phụ nữ mang thai, đang cho con bú, người đang dùng thuốc chống đông máu, người chuẩn bị phẫu thuật, trẻ em và người có tiền sử dị ứng với thành phần của tam thất cần tránh hoặc hỏi ý kiến bác sĩ trước khi dùng."
    }
  }]
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Uống trà nụ hoa tam thất mỗi ngày bao nhiêu nụ là đủ?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Người lớn khỏe mạnh nên dùng 3–5 nụ (khoảng 2–3g) cho mỗi tách 250–300ml, tối đa 1–2 tách/ngày. Người mới dùng nên bắt đầu với 2–3 nụ loãng trong 3–5 ngày đầu."
      }
    },
    {
      "@type": "Question",
      "name": "Trà nụ hoa tam thất có caffeine không?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Nụ hoa tam thất hầu như không chứa caffeine, thấp hơn nhiều so với trà xanh và cà phê, nên thường được chọn làm thức uống buổi tối. Người nhạy cảm nên uống đầu buổi tối thay vì sát giờ ngủ."
      }
    },
    {
      "@type": "Question",
      "name": "Uống trà nụ hoa tam thất bao lâu thì cảm nhận hiệu quả?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Nhiều người dùng phản hồi giấc ngủ sâu và êm hơn sau 7–10 ngày uống đều đặn. Đây là mốc tham khảo cá nhân, không phải cam kết hiệu quả; trà thảo mộc không thay thế thuốc chữa bệnh."
      }
    },
    {
      "@type": "Question",
      "name": "Phụ nữ mang thai có uống trà nụ hoa tam thất được không?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Không. Phụ nữ mang thai và đang cho con bú không nên tự ý dùng chế phẩm từ tam thất khi chưa có chỉ định của bác sĩ do dữ liệu an toàn còn hạn chế."
      }
    },
    {
      "@type": "Question",
      "name": "Những ai không nên uống trà nụ hoa tam thất?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Phụ nữ mang thai hoặc đang cho con bú, người đang dùng thuốc chống đông máu, người huyết áp thấp, người chuẩn bị phẫu thuật, trẻ em dưới 12 tuổi và người dị ứng với cây họ Nhân sâm cần tránh hoặc hỏi ý kiến bác sĩ trước khi dùng."
      }
    }
  ]
}
